Certainly! Below is an example of a complex smart contract written in Solidity, the programming language used for Ethereum smart contracts. This contract is designed to facilitate a decentralized voting system with multiple features, including voter registration, candidate registration, voting, and result tallying.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool registered;
        bool voted;
        uint256 vote;
    }

    struct Candidate {
        string name;
        uint256 voteCount;
    }

    address public admin;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    bool public votingEnded;

    event VoterRegistered(address indexed voter);
    event VoterVoted(address indexed voter, uint256 vote);
    event CandidateRegistered(string name);
    event VotingEnded();

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can call this function.");
        _;
    }

    modifier onlyRegisteredVoter() {
        require(voters[msg.sender].registered, "Only registered voters can call this function.");
        _;
    }

    modifier onlyVotingActive() {
        require(!votingEnded, "Voting has already ended.");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerVoter(address voter) public onlyAdmin {
        require(!voters[voter].registered, "Voter is already registered.");
        voters[voter].registered = true;
        emit VoterRegistered(voter);
    }

    function registerCandidate(string memory name) public onlyAdmin {
        candidates.push(Candidate(name, 0));
        emit CandidateRegistered(name);
    }

    function vote(uint256 candidateIndex) public onlyRegisteredVoter onlyVotingActive {
        require(!voters[msg.sender].voted, "Voter has already voted.");
        require(candidateIndex < candidates.length, "Invalid candidate index.");

        voters[msg.sender].voted = true;
        voters[msg.sender].vote = candidateIndex;
        candidates[candidateIndex].voteCount += 1;

        emit VoterVoted(msg.sender, candidateIndex);
    }

    function endVoting() public onlyAdmin {
        votingEnded = true;
        emit VotingEnded();
    }

    function getCandidateCount() public view returns (uint256) {
        return candidates.length;
    }

    function getCandidate(uint256 index) public view returns (string memory, uint256) {
        require(index < candidates.length, "Invalid candidate index.");
        return (candidates[index].name, candidates[index].voteCount);
    }

    function getVoterCount() public view returns (uint256) {
        uint256 count = 0;
        for (uint256 i = 0; i < candidates.length; i++) {
            if (voters[msg.sender].registered) {
                count += 1;
            }
        }
        return count;
    }
}
```

This smart contract includes the following features:
- Voter registration and management
- Candidate registration and management
- Voting functionality with checks to ensure only registered voters can vote and that they can only vote once
- Event logging for key actions
- Functions to end voting and retrieve candidate and voter counts

This is a basic example, and a real-world smart contract would likely include additional features and security measures, such as time locks, more complex voting rules, and security audits.

